static volatile sig_atomic_t stopflag=0;
void sig(int){stopflag=1;}
string readfile(string p){ifstream f(p,ios::binary);return string(istreambuf_iterator<char>(f),{});}
string low(string s){for(char &c:s)c=tolower((unsigned char)c);return s;}
int main(int argc,char**argv){signal(SIGPIPE,SIG_IGN);signal(SIGTERM,sig);if(argc!=3)return 1;string conf=readfile(argv[2]);if(conf.empty())return 1;if(string(argv[1])=="--check-config")return 0;if(string(argv[1])!="--config")return 1;smatch m;int port=8080;string root="/www";if(regex_search(conf,m,regex("listen[ \\t]+127\\.0\\.0\\.1:([0-9]+)")))port=stoi(m[1]);if(regex_search(conf,m,regex("root[ \\t]+([^; \\t\\r\\n]+)")))root=m[1];int l=socket(AF_INET,SOCK_STREAM,0),one=1;setsockopt(l,SOL_SOCKET,SO_REUSEADDR,&one,sizeof(one));sockaddr_in a{};a.sin_family=AF_INET;a.sin_addr.s_addr=htonl(INADDR_LOOPBACK);a.sin_port=htons(port);if(bind(l,(sockaddr*)&a,sizeof(a))||listen(l,1024))return 1;fcntl(l,F_SETFL,O_NONBLOCK);struct Conn{int fd;string in,out;bool close=false;};vector<Conn> cs;while(!stopflag){vector<pollfd> ps{{l,POLLIN,0}};for(auto &c:cs)ps.push_back({c.fd,(short)(c.out.empty()?POLLIN:POLLOUT),0});int n=poll(ps.data(),ps.size(),100);if(n<0)continue;if(ps[0].revents&POLLIN){int x;while((x=accept(l,nullptr,nullptr))>=0){fcntl(x,F_SETFL,O_NONBLOCK);cs.push_back({x});}}size_t old=ps.size()-1;for(size_t i=0;i<old;i++){auto &c=cs[i];auto ev=ps[i+1].revents;if(ev&(POLLERR|POLLHUP|POLLNVAL)){c.close=true;c.out.clear();continue;}if(ev&POLLIN){char b[8192];int r=recv(c.fd,b,sizeof(b),0);if(r<=0){c.close=true;continue;}c.in.append(b,r);if(c.in.size()>65536){c.close=true;continue;}}if(c.out.empty()){auto end=c.in.find("\r\n\r\n");if(end!=string::npos){string h=c.in.substr(0,end+4);c.in.erase(0,end+4);istringstream ss(h);string method,path,version;ss>>method>>path>>version;bool cl=low(h).find("connection: close")!=string::npos||version=="HTTP/1.0";int status=200;string body,type="application/octet-stream",extra;auto q=path.find('?');if(q!=string::npos)path.resize(q);if(path.empty()||path[0]!='/'||path.find("..")!=string::npos||path.find('\\')!=string::npos)status=400;else if(method!="GET"&&method!="HEAD")status=405;else {string p=root+path;struct stat st{};if(stat(p.c_str(),&st))status=404;else if(!S_ISREG(st.st_mode))status=403;else {body=readfile(p);if(path.size()>=4&&path.substr(path.size()-4)==".txt")type="text/plain";}}string reason=status==200?"OK":status==404?"Not Found":status==403?"Forbidden":status==405?"Method Not Allowed":"Bad Request";c.out="HTTP/1.1 "+to_string(status)+" "+reason+"\r\nContent-Length: "+to_string(body.size())+"\r\nContent-Type: "+type+"\r\nConnection: "+(cl?"close":"keep-alive")+"\r\n\r\n"+(method=="HEAD"?"":body);c.close=cl;}}if((ev&POLLOUT)&&!c.out.empty()){int w=send(c.fd,c.out.data(),c.out.size(),MSG_NOSIGNAL);if(w>0)c.out.erase(0,w);else if(w<0&&errno!=EAGAIN&&errno!=EWOULDBLOCK)c.close=true;} }for(size_t i=0;i<cs.size();){if(cs[i].close&&cs[i].out.empty()){close(cs[i].fd);cs.erase(cs.begin()+i);}else i++;}}for(auto &c:cs)close(c.fd);close(l);return 0;}
